/** Options for renderFeedback(container, DEMO_ASSESSMENT, demoOptions(hints, onTryAgain)). */
export function demoOptions(hints, onTryAgain) {
  return {
    demo: { label: DEMO_LABEL, transcriptLabel: DEMO_TRANSCRIPT_LABEL },
    coaching: analyseCoaching(turnsFromAssessment(DEMO_ASSESSMENT), hints),   // real coaching logic on the simulated transcript
    strategyDetails: STRATEGY_DETAILS,
    criterionDetails: Object.fromEntries(DIMENSIONS.map((d) => [d.id, { level: level(d.score), good: d.good, recommendation: d.recommendation }])),
    learningObjective: 'In your next consultation, steer back to the clinical question after every side story, and give one interim and one closing summary.',
    issues: DEMO_ISSUES,
    practiceSteps: PRACTICE_STEPS,
    progress: PROGRESS,
    onTryAgain
  };
}
